payload.input:
const r=await Promise.allSettled([
tools.exec_command({cmd:".venv/bin/python - <<'PY'
import json
from pathlib import Path
from collections import Counter
annotations=[json.loads(l) for l in Path('artifacts/annotations-training.jsonl').read_text().splitlines()]
uncited=[]; words=[]; byphase=Counter()
for r in annotations:
 a=r['annotation']; cited=set()
 for c in a['precursor_patterns']+a['interaction_hypotheses']:cited.update(c['channels'])
 for action in a['recommended_actions']:
  if not set(action['driver_channels'])<=cited:uncited.append(r['sample_id'])
 words.append(len(a['rationale'].split())+sum(len(x['action'].split()) for x in a['recommended_actions']))
 byphase[a['observed_future_phase']]+=1
print('Annotated label distribution',dict(byphase))
print('Actions with drivers absent from precursor/interaction citations',len(uncited),'in unique samples',len(set(uncited)))
words.sort(); print('Target rationale+action word lengths',{'median':words[len(words)//2],'p90':words[int(len(words)*.9)],'max':max(words),'over_200':sum(w>200 for w in words)})
for r in annotations[:2]:
 a=r['annotation'];print(json.dumps({'sample_id':r['sample_id'],'rationale':a['rationale'],'actions':a['recommended_actions']},ensure_ascii=False))
PY","max_output_tokens":3000}),
tools.exec_command({cmd:"nl -ba src/open_relief/gpu.py | sed -n '20,170p'; nl -ba src/open_relief/adapter.py | sed -n '30,80p'; nl -ba scripts/upload_to_nebius.sh; nl -ba scripts/package_handoff.py | sed -n '1,45p'; git rev-parse --short HEAD; git ls-files --unmerged","max_output_tokens":4600}),
tools.write_stdin({session_id:88620,chars:"","yield_time_ms":1000,"max_output_tokens":1000})
]);r.forEach(text);

