   e.preventDefault();e.stopPropagation();setHovered(null);
   const factor=e.deltaMode===1?16:e.deltaMode===2?300:1;
   if(Math.abs(e.deltaX)>Math.abs(e.deltaY)&&!e.ctrlKey){
