  <div className="landing-footer"><span>INTELLIGENCE FOR HUMANITY</span><span>47.3769° N &nbsp; 8.5417° E</span></div>
 </div>;

 return <div className="app-shell dark-dashboard">
  {view!=='map'&&<MapBackdrop countries={countries} forecasts={forecasts} color={color}/>}
  {cursorEnabled&&view==='map'&&!dragging&&<TargetCursor key={`${zoom}-${center.join()}-${view}`} targetSelector=".country" scopeSelector=".world-map" hideDefaultCursor={false} spinDuration={5} parallaxOn={false} cursorColor="#cccccc"/>}
  {hovered&&<div className="country-tooltip" style={{left:hovered.x,top:hovered.y}}><span>{hovered.name}</span><strong style={{color:hovered.risk!==null?color(hovered.risk):'#aaa'}}>{hovered.risk!==null?`${hovered.risk}%`:'No data'}</strong><small>DEMO RISK</small></div>}
  <header><a href="#" onClick={()=>setStarted(false)} className="brand"><svg className="relief-logo" width="34" height="34" viewBox="0 0 40 40" fill="none" aria-hidden="true"><path d="M30.5 8.5A15.5 15.5 0 1 0 35 24" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" opacity=".65"/><path d="M19.5 31V13" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round"/><path d="M19.5 14C16 11 17 7.5 19.5 5.5C22 7.5 23 11 19.5 14ZM19.5 20C14 20 11 16.5 11.5 12.5C16 12.5 19.5 15.5 19.5 20ZM19.5 26C14 26 10.5 23 11 19C15.5 19 19.5 22 19.5 26ZM19.5 20C25 20 28 16.5 27.5 12.5C23 12.5 19.5 15.5 19.5 20ZM19.5 26C25 26 28.5 23 28 19C23.5 19 19.5 22 19.5 26Z" fill="currentColor"/><circle cx="34" cy="15" r="2.5" fill="currentColor"/><circle cx="34" cy="15" r="5" stroke="currentColor" strokeWidth=".8" opacity=".3"/></svg> OpenRelief<span className="brand-dot">®</span></a><nav><button className={view==='map'?'nav-active':''} onClick={()=>setView('map')}>Risk overview</button><button className={view==='signals'?'nav-active':''} onClick={()=>setView('signals')}>Global insights</button><button className={view==='methodology'?'nav-active':''} onClick={()=>setView('methodology')}>Our methodology <ArrowUpRight size={13}/></button><button className={view==='roadmap'?'nav-active':''} onClick={()=>setView('roadmap')}>Roadmap</button></nav><span className="prototype"><i/> Research preview</span></header>
  <main>  <section className="workspace">
