  {detailTab==='outlook'?<><div className="probability"><span>{activeRisk}<small>%</small></span><span className="risk-badge" style={{color:color(activeRisk),background:color(activeRisk)+'26'}}>{category(activeRisk)} risk</span></div><p className="probability-label">Risk of increased food insecurity<br/>in the next {horizon} days</p><div className="confidence-card"><div><span>Prediction confidence</span><strong>{explanation.confidence}<small>%</small></strong></div><div className="confidence-bar"><i style={{width:explanation.confidence+'%'}}/></div><p>Illustrative score · Not calibrated accuracy</p></div><div className="price-card"><span className="section-kicker">PRICE OBSERVATION</span><div><strong>${explanation.price.current}<small> / tonne</small></strong><span>+{explanation.price.changePct}% <ArrowUpRight size={13}/></span></div><p>{explanation.price.commodity}</p><small>From ${explanation.price.previous} · {explanation.price.period}</small></div><button className="explanation-preview" onClick={()=>setDetailTab('explanation')}><span>What could explain this?</span><strong>{explanation.title}</strong><ArrowRight size={16}/></button></>:detailTab==='explanation'?<><span className="section-kicker">POSSIBLE EXPLANATION</span><h4>{explanation.title}</h4><p>{explanation.hypothesis}</p><span className="section-kicker">HOW THE PREDICTION IS FORMED</span><p>{explanation.method}</p><div className="uncertainty-note"><Info size={15}/><p>{explanation.limitation}</p></div><p className="hypothesis-note">A hypothesis is not proof of causation. This scenario is fictional.</p></>:<><span className="section-kicker">EVIDENCE & PROVENANCE</span><p>The model will return the records supporting each explanation, including their origin and observation date.</p>{explanation.sources.map(source=><div className="source-row" key={source.id}><span>{source.name}</span><small>{source.status}</small></div>)}<div className="source-metadata"><span>Model version <strong>Awaiting integration</strong