frontend/src/components/Methodology.css
.method-page{height:100%;overflow:auto;overscroll-behavior:contain;scrollbar-width:thin;padding:36px 5% 100px}
.method-intro{max-width:700px}
.method-intro .eyebrow{color:#aaa;font-size:10px}
.method-intro h1{font-family:Manrope;font-size:38px;line-height:1.2;letter-spacing:-1.7px;font-weight:500;margin:16px 0}
.method-intro>p{font-size:14px;color:#aaa;line-height:1.8;max-width:560px}
.method-column-labels{display:grid;grid-template-columns:1fr 1fr 1fr;margin:34px 0 18px;font-size:9px;letter-spacing:1.2px;color:#999}
.method-column-labels>span:nth-child(2){text-align:center}
.method-column-labels>span:last-child{text-align:right}
.method-flow{height:480px;position:relative;display:grid;grid-template-columns:27% 30% 27%;justify-content:space-between}
.flow-wires{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;overflow:visible}
.flow-wires path{fill:none;stroke:#aaa;stroke-width:1;stroke-opacity:.23;vector-effect:non-scaling-stroke;transition:stroke-opacity .25s}
.wire-pulse{fill:#ddd}
.input-stack,.output-stack,.model-column{position:relative;z-index:1}
.input-stack{display:flex;flex-direction:column;justify-content:space-between}
.signal-node{position:relative;display:flex;align-items:center;gap:13px;border:1px solid #ffffff1b;border-radius:12px;background:#202020bd;backdrop-filter:blur(15px);padding:18px;text-align:left;height:84px;width:100%;transition:background .2s,border-color .2s}
.signal-node>svg{color:#999;flex-shrink:0}
.signal-node>span:nth-child(2){display:flex;flex-direction:column;gap:6px}
.signal-node strong{font-size:13px;font-weight:500;color:#ddd}
.signal-node small{font-size:10px;color:#888}
.node-port{position:absolute;right:-3px;width:5px;height:5px;background:#aaa;border-radius:50%;box-shadow:0 0 12px #fff3}
.model-column{display:flex;justify-content:center;align-items:center}
.model-node{width:100%;border:1px solid #ffffff2c;background:linear-gradient(135deg,#343434bd,#1b1b1bcc);box-shadow:0 0 70px #ffffff05,inset 0 1px 0 #ffffff12;border-radius:19px;padding:28px 22px;backdrop-filter:blur(20px);text-align:center}
frontend/src/components/MapBackdrop.css
/* A shared, flat, softly blurred world map behind informational pages. */
.decorative-map{position:absolute;inset:0;overflow:hidden;pointer-events:none;z-index:0;isolation:isolate}
.decorative-map svg{position:absolute;width:var(--world-map-width);max-width:none;height:auto;left:50%;top:var(--world-map-top);transform:translate(-50%,-35%);filter:blur(3px);opacity:.35;mask-image:linear-gradient(transparent,#000 22%,#000 72%,transparent)}
.decorative-map-shade{position:absolute;inset:0;background:linear-gradient(180deg,#0b0b0b55,transparent 40%,#09090965)}
.landing{position:relative;isolation:isolate}
.landing-content,.landing-footer{position:relative;z-index:1}
.dark-dashboard{position:relative;isolation:isolate}
.dark-dashboard>main{position:relative;z-index:1}
.roadmap,.model-insights{background:transparent}
.roadmap-grid article,.insight-grid article,.provenance-banner{background:#20202090;backdrop-filter:blur(14px)}
@media(max-width:700px){.decorative-map svg{width:var(--world-map-width);top:var(--world-map-top);filter:blur(2.5px)}
}

